from html.parser import HTMLParser
import re

def parse_file(path):
    with open(path, 'r', encoding='utf-8') as f:
        html = f.read()
    cleaned = re.sub(r'data:image/[^"]+', '[IMAGE_DATA]', html)
    lines = []
    class P(HTMLParser):
        def __init__(self):
            super().__init__()
            self.in_pre = False
        def handle_starttag(self, tag, attrs):
            if tag in ['h1', 'h2', 'h3', 'h4']:
                lines.append(f"\n### {tag.upper()} ###")
            elif tag == 'pre':
                self.in_pre = True
                lines.append("\n```")
        def handle_endtag(self, tag):
            if tag == 'pre':
                self.in_pre = False
                lines.append("```\n")
        def handle_data(self, data):
            t = data.strip() if not self.in_pre else data
            if t:
                lines.append(t)
    p = P()
    p.feed(cleaned)
    return '\n'.join(lines)

