    attributes={
        "neatlogs.guardrail.name": "anti_double_billing_gate",
        "neatlogs.guardrail.triggered": has_duplicate,
        "neatlogs.guardrail.passed": not has_duplicate,
        "neatlogs.guardrail.score": 0.95 if has_duplicate else 1.0,
        "neatlogs.guardrail.reason": "Flagged duplicate disbursement violating municipal AP integrity" if has_duplicate else "All payments verified distinct",
        "neatlogs.guardrail.action": "ESCALATE_FOR_CLAWBACK" if has_duplicate else "PASS"
    }
) as guard_span:
    guard_span["input"] = {"candidates_analyzed": len(adjudicated_findings)}
    guard_span["output"] = {
        "violations_detected": len([f for f in adjudicated_findings if f.get("is_duplicate")]),
        "status": "FLAGGED" if has_duplicate else "CLEARED"
    }

