import { NextRequest, NextResponse } from "next/server";
import { execFile } from "child_process";
import path from "path";
import fs from "fs/promises";

export async function POST(req: NextRequest) {
  try {
    const contentType = req.headers.get("content-type") || "";
    let filePath: string | null = null;
    let datasetName = "ok";
    let isTempFile = false;

    if (contentType.includes("multipart/form-data")) {
      const formData = await req.formData();
      const file = formData.get("file") as File | null;
      const datasetParam = formData.get("dataset") as string | null;

      if (datasetParam) {
        datasetName = datasetParam;
      }

      if (file && file.size > 0) {
        const buffer = Buffer.from(await file.arrayBuffer());
        const tempFileName = `temp_upload_${Date.now()}_${file.name.replace(/[^a-zA-Z0-9._-]/g, "_")}`;
        const tempFilePath = path.join(process.cwd(), "data", "samples", tempFileName);
        await fs.writeFile(tempFilePath, buffer);
        filePath = tempFilePath;
        isTempFile = true;
      }
    } else {
      const body = await req.json().catch(() => ({}));
      if (body.dataset) {
        datasetName = body.dataset;
      }
      if (body.filePath) {
        filePath = body.filePath;
      }
    }

    const scriptPath = path.join(process.cwd(), "scripts", "audit_api_bridge.py");
    const pythonExe = process.platform === "win32" ? "python" : "python3";

    const args = [scriptPath];
    if (filePath) {
      args.push("--file", filePath);
    } else {
      args.push("--dataset", datasetName);
    }
    args.push("--limit", "3");
    args.push("--mode", "investigator");

    const auditPromise = new Promise<{ stdout: string; stderr: string }>((resolve, reject) => {
      execFile(
        pythonExe,
        args,
        {
          cwd: process.cwd(),
          timeout: 45000,
          maxBuffer: 10 * 1024 * 1024,
          env: { ...process.env }
        },
        (error, stdout, stderr) => {
          if (error) {
            reject(error);
          } else {
            resolve({ stdout, stderr });
          }
        }
      );
    });

    const { stdout } = await auditPromise;

    // Clean up temp file if one was written
    if (isTempFile && filePath) {
      try {
        await fs.unlink(filePath);
      } catch {
        // ignore cleanup error
      }
    }

    // Extract JSON from output
    const match = stdout.match(/AUDIT_JSON_OUTPUT:(.*)/);
    if (match && match[1]) {
      const parsedData = JSON.parse(match[1].trim());
      return NextResponse.json({
        success: true,
        source: "live_python_agent",
        ...parsedData
      });
    }

    return NextResponse.json({
      success: false,
      error: "No structured audit output found in script execution",
      rawOutput: stdout
    }, { status: 500 });

  } catch (error: any) {
    console.error("API Audit Error:", error);
    return NextResponse.json({
      success: false,
      error: error.message || "Failed to execute autonomous audit agent"
    }, { status: 500 });
  }
}

