      const poIdx = headers.findIndex(h => h.includes("po") || h.includes("purchase_order") || h.includes("contract"));
      const methodIdx = headers.findIndex(h => h.includes("method") || h.includes("type"));
      const statusIdx = headers.findIndex(h => h.includes("status"));
