export default function AgentWorkspacePage() {
  const [findings, setFindings] = useState<Finding[]>(INITIAL_FINDINGS);
  const [selectedFindingId, setSelectedFindingId] = useState<string>("la-parks-12818");
  const [activeDatasetLabel, setActiveDatasetLabel] = useState<string>("City of Los Angeles (20,139 rows)");
  const [activeRowCount, setActiveRowCount] = useState<number>(20139);
  const [isProcessingFile, setIsProcessingFile] = useState<boolean>(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Helper to parse CSV lines safely with quotes
  const parseCSVLine = (text: string) => {
    const result: string[] = [];
    let cur = "";
    let inQuotes = false;
    for (let i = 0; i < text.length; i++) {
      const c = text[i];
      if (c === '"') {
        if (inQuotes && text[i + 1] === '"') {
          cur += '"';
          i++;
        } else {
          inQuotes = !inQuotes;
        }
      } else if (c === ',' && !inQuotes) {
        result.push(cur.trim());
        cur = "";
      } else {
        cur += c;
      }
    }
    result.push(cur.trim());
    return result;
  };

  // Synchronize with active audit session from Command Center or previous uploads
  useEffect(() => {
    try {
      const savedRaw = localStorage.getItem("ovio_active_audit");
      if (savedRaw) {
        const saved = JSON.parse(savedRaw);
        if (saved.finding) {
          setFindings(prev => {
            const existingIdx = prev.findIndex(f => f.id === saved.finding.id || f.vendor === saved.finding.vendor);
            if (existingIdx >= 0) {
              const copy = [...prev];
              copy[existingIdx] = saved.finding;
              return copy;
            }
            return [saved.finding, ...prev];
          });
          setSelectedFindingId(saved.finding.id);
          setActiveDatasetLabel(saved.finding.dataset || saved.fileName || "Custom Ledger");
          setActiveRowCount(saved.rowCount || 100);
        } else if (saved.datasetId === "ok") {
          setSelectedFindingId("ok-cdw-4095");
          setActiveDatasetLabel("State of Oklahoma (4,693 rows)");
          setActiveRowCount(4693);
        } else if (saved.datasetId === "la") {
          setSelectedFindingId("la-parks-12818");
          setActiveDatasetLabel("City of Los Angeles (20,139 rows)");
          setActiveRowCount(20139);
        } else if (saved.datasetId === "enterprise") {
          setSelectedFindingId("ent-deloitte-42000");
          setActiveDatasetLabel("Enterprise B2B SaaS (30 rows)");
          setActiveRowCount(30);
        } else if (saved.datasetId === "chicago") {
          setSelectedFindingId("chi-transit-45200");
          setActiveDatasetLabel("City of Chicago (1,968 rows)");
          setActiveRowCount(1968);
        }
      }
    } catch (e) {
      console.warn("Storage reading error:", e);
    }
  }, []);

  // Direct CSV file upload on Review Queue desk
  const handleDirectCSVUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessingFile(true);
    const reader = new FileReader();

    reader.onload = async (event) => {
