"use client";

import React, { useEffect, useState, useTransition } from "react";
import { usePathname } from "next/navigation";

export default function NavigationProgressBar() {
  const pathname = usePathname();
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);

  // When pathname changes, complete and reset progress
  useEffect(() => {
    if (loading) {
      setProgress(100);
      const timer = setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [pathname]);

  // Intercept click on internal links
  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      const target = (e.target as HTMLElement)?.closest("a");
      if (!target) return;

      const href = target.getAttribute("href");
      if (!href) return;

      // Only trigger for internal links that differ from current pathname
      if (
        href.startsWith("/") &&
        !href.startsWith("//") &&
        !target.getAttribute("target") &&
        !target.getAttribute("download") &&
        !e.ctrlKey &&
        !e.metaKey &&
        !e.shiftKey &&
        !e.altKey
      ) {
        const targetPath = href.split("?")[0].split("#")[0];
        const currentPath = window.location.pathname;

        if (targetPath !== currentPath) {
          setLoading(true);
          setProgress(25);
        }
      }
    };

    document.addEventListener("click", handleClick, { capture: true });
    return () => document.removeEventListener("click", handleClick, { capture: true });
  }, []);

  // Increment progress gradually while loading
  useEffect(() => {
    if (!loading) return;

    const interval = setInterval(() => {
      setProgress((prev) => {
        if (prev >= 85) return prev;
        return prev + (prev < 50 ? 20 : 10);
      });
    }, 150);

    return () => clearInterval(interval);
  }, [loading]);

  if (!loading && progress === 0) return null;

  return (
    <>
      {/* TOP GLOWING PROGRESS BAR */}
      <div
        style={{
          position: "fixed",
          top: 0,
          left: 0,
          height: "3px",
          width: `${progress}%`,
          background: "linear-gradient(90deg, #16a34a, #22c55e, #4ade80)",
          boxShadow: "0 0 12px rgba(34, 197, 94, 0.8)",
          zIndex: 99999,
          transition: progress === 100 ? "width 0.2s ease, opacity 0.3s ease" : "width 0.2s ease",
          opacity: progress === 100 ? 0 : 1,
          pointerEvents: "none",
        }}
      />

      {/* FLOATING TOP-RIGHT MINIMALIST NAVIGATION INDICATOR */}
      <div
        style={{
          position: "fixed",
          top: "14px",
          right: "24px",
          zIndex: 99999,
          display: "inline-flex",
          alignItems: "center",
          gap: "8px",
          background: "rgba(9, 9, 11, 0.92)",
          backdropFilter: "blur(12px)",
          color: "#ffffff",
          padding: "5px 12px",
          borderRadius: "20px",
          fontSize: "12px",
          fontWeight: 600,
          boxShadow: "0 4px 16px rgba(0, 0, 0, 0.2)",
          border: "1px solid rgba(255, 255, 255, 0.15)",
          animation: "fadeIn 0.15s ease-in-out",
          pointerEvents: "none",
        }}
      >
        <span
          style={{
            width: "8px",
            height: "8px",
            borderRadius: "50%",
            background: "#22c55e",
            boxShadow: "0 0 8px #22c55e",
            display: "inline-block",
            animation: "pulseDot 1s infinite alternate",
          }}
        />
        <span>Loading view...</span>
      </div>

      <style jsx global>{`
        @keyframes pulseDot {
          from { opacity: 0.4; transform: scale(0.85); }
          to { opacity: 1; transform: scale(1.15); }
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(-4px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </>
  );
}

import React from "react";

export default function Loading() {
  return (
    <div
      style={{
        minHeight: "70vh",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        gap: "18px",
        background: "#ffffff",
        color: "#09090b",
      }}
    >
      <div
        style={{
          position: "relative",
          width: "48px",
          height: "48px",
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            borderRadius: "50%",
            border: "3px solid #e4e4e7",
            borderTopColor: "#16a34a",
            animation: "spin 0.8s linear infinite",
          }}
        />
        <div
          style={{
            position: "absolute",
            inset: "8px",
            background: "#09090b",
            color: "#ffffff",
            borderRadius: "50%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: "11px",
            fontWeight: 800,
          }}
        >
          O
        </div>
      </div>

      <div style={{ textAlign: "center" }}>
        <div style={{ fontSize: "14px", fontWeight: 700, color: "#09090b" }}>
          Loading review data...
        </div>
        <div style={{ fontSize: "12px", color: "#71717a", marginTop: "2px" }}>
          Synchronizing state with Ovio engine
        </div>
      </div>

      <style>{`
        @keyframes spin {
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
}

